<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="theme-color" content="#17242c">
<meta name="description" content="Dune Line — an overnight rail journey from the open desert of Sola Dunes to the neon streets of Luma City.">
<title>Dune Line — Desert nights. Neon lights.</title>
<style>
  :root {
    --night:#17242c; --deep:#111d24; --cream:#f5f1e7; --paper:#ebe6d9;
    --ink:#202d32; --muted:#5c6565; --line:#ccc9bd; --orange:#ffae77;
    --rust:#9c4929; --pale:#bdc4c1; --serif:Georgia,"Times New Roman",serif;
    --sans:Arial,Helvetica,sans-serif; --mono:"Courier New",monospace;
  }
  *,*::before,*::after{box-sizing:border-box}
  html{scroll-behavior:smooth;scroll-padding-top:22px}
  body{margin:0;background:var(--cream);color:var(--ink);font:16px/1.55 var(--sans);-webkit-font-smoothing:antialiased}
  a{color:inherit;text-decoration:none}
  button,select{font:inherit}
  button,a,select{-webkit-tap-highlight-color:transparent}
  button{cursor:pointer}
  button:focus-visible,a:focus-visible,select:focus-visible{outline:3px solid #cb743f;outline-offset:4px}
  button{color:inherit}
  svg{display:block}
  figure,h1,h2,h3,p,blockquote{margin:0}
  .defs{position:absolute;width:0;height:0;overflow:hidden}
  .wrap{width:min(1440px,100%);margin:auto;padding-inline:clamp(24px,5.4vw,84px)}
  .mono,.kicker,.tag,th,.small-label{font:700 10px/1.4 var(--mono);letter-spacing:.14em;text-transform:uppercase}
  .icon{width:18px;height:18px;flex:none;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}
  .dark{background:var(--night);color:var(--cream)}
  .skip{position:fixed;left:12px;top:-100px;z-index:10;background:var(--cream);color:var(--ink);padding:10px 20px}
  .skip:focus{top:10px}
  .nav{height:78px;display:flex;align-items:center;justify-content:space-between;gap:28px;border-bottom:1px solid #ffffff24}
  .brand{display:inline-flex;align-items:center;gap:10px;white-space:nowrap;font-weight:700;font-size:25px;letter-spacing:-1.45px;line-height:1}
  .brand-mark{width:42px;height:31px;color:var(--orange)}
  .nav-links{display:flex;gap:34px;margin-left:auto;margin-right:13px}
  .nav-links a,.footer-links a{font-size:13px;color:#d6dad5;transition:color .2s}
  .nav-links a:hover,.footer-links a:hover{color:var(--orange)}
  .btn{display:inline-flex;align-items:center;justify-content:center;gap:19px;padding:14px 21px;border-radius:3px;border:1px solid transparent;font-size:13px;font-weight:700;line-height:1.4;transition:background .18s,color .18s,border-color .18s}
  .btn .icon{transition:transform .2s}
  .btn:hover .icon{transform:translateX(3px)}
  .btn-peach{background:var(--orange);color:var(--deep)}
  .btn-peach:hover{background:#ffc294}
  .btn-outline{background:transparent;border-color:#687379;color:var(--cream);padding:9px 16px}
  .btn-outline:hover{background:#ffffff0d;border-color:var(--cream)}
  .hero{display:grid;grid-template-columns:.92fr 1.15fr;gap:clamp(28px,4.5vw,70px);align-items:center;padding:55px 0 47px}
  .kicker{display:flex;align-items:center;gap:12px;color:var(--rust);letter-spacing:.16em}
  .kicker::before{content:"";display:block;width:27px;height:2px;background:currentColor}
  .hero .kicker{color:var(--orange)}
  h1,h2,h3,blockquote{font-family:var(--serif);font-weight:normal}
  h1{font-size:clamp(66px,6.6vw,103px);letter-spacing:-.063em;line-height:.99;margin:24px 0 20px}
  h1 em{font-weight:normal;color:var(--orange);letter-spacing:-.068em}
  .intro{font-size:clamp(15px,1.22vw,18px);line-height:1.7;max-width:370px;color:#cad0cd}
  .hero-cta{margin-top:27px}
  .plate{position:relative;min-width:0;padding:7px;border:1px solid #74808488;background:#1e2b33;box-shadow:0 9px 30px #0b15171a}
  .scene{width:100%;height:auto;background:#263446}
  .plate figcaption{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:9px 3px 1px;color:#c7cbc4;font:10px/1.4 var(--mono);letter-spacing:.08em;text-transform:uppercase}
  .plate figcaption span:first-child{color:#e9b08c}
  .route-strip{border-top:1px solid #ffffff2b;display:flex;align-items:center;min-height:77px;gap:32px}
  .route-label{display:flex;align-items:center;gap:9px;color:var(--orange);white-space:nowrap}
  .route-label .icon{width:21px;height:21px}
  .stops{display:flex;align-items:center;gap:13px;font-size:13px;font-weight:600}
  .stop-line{display:block;height:1px;width:clamp(46px,7vw,108px);background:#89918e;position:relative}
  .stop-line::after,.stop-line::before{content:"";position:absolute;width:6px;height:6px;border:1px solid var(--orange);background:var(--night);border-radius:50%;top:-2.5px}
  .stop-line::after{right:0}
  .route-stats{margin-left:auto;display:flex;align-items:center;gap:25px;color:#d3d8d4;font:11px var(--mono);letter-spacing:.06em}
  .route-stats span{display:flex;align-items:center;gap:8px}
  .route-stats span+span{border-left:1px solid #ffffff30;padding-left:25px}
  .route-stats .icon{width:15px;height:15px;color:var(--orange)}
  .section{padding-block:75px}
  .section-head{display:flex;align-items:flex-end;justify-content:space-between;gap:30px;margin-bottom:35px}
  h2{font-size:clamp(42px,4.35vw,67px);letter-spacing:-.055em;line-height:1.07}
  .section-head h2,.fare-intro h2{margin-top:13px}
  .section-note{color:var(--muted);font-size:14px;line-height:1.6;max-width:260px;padding-bottom:3px}
  .features{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid var(--line);padding-top:24px}
  .feature{padding:0 31px;border-right:1px solid var(--line)}
  .feature:first-child{padding-left:0}
  .feature:last-child{border:0;padding-right:0}
  .feature-top{display:flex;align-items:center;justify-content:space-between;margin-bottom:20px}
  .feature-art{width:51px;height:42px;stroke:var(--rust);fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-width:1.45}
  .feature-top .mono{color:#7c8079;font-weight:400}
  h3{font-size:29px;line-height:1.2;letter-spacing:-.045em}
  .feature p,.fare-card p{font-size:14px;line-height:1.7;color:var(--muted);margin-top:9px;max-width:340px}
  .schedule{background:var(--paper);border-block:1px solid var(--line)}
  .schedule-head-note{display:flex;align-items:center;gap:9px;color:var(--muted);font:11px var(--mono);letter-spacing:.04em;padding-bottom:6px}
  .light{width:7px;height:7px;display:inline-block;background:#577956;border-radius:100%;box-shadow:0 0 0 3px #5779561c}
  table{width:100%;border-collapse:collapse;text-align:left;font-variant-numeric:tabular-nums}
  th{color:var(--muted);border-top:2px solid var(--ink);padding:12px 10px;background:#ffffff2b}
  th:first-child,td:first-child{padding-left:15px}
  td{border-top:1px solid #c7c4b7;padding:16px 10px}
  tbody tr:last-child{border-bottom:1px solid #a9ac9f}
  tbody tr:hover{background:#ffffff38}
  .service{display:flex;align-items:center;gap:18px}
  .service b{font:700 11px var(--mono);letter-spacing:.08em;color:var(--rust)}
  .service-name{font-family:var(--serif);font-size:21px;letter-spacing:-.035em}
  .time{font:19px var(--mono);letter-spacing:-.045em}
  .time sup{font-size:10px;color:var(--rust);vertical-align:top;margin-left:3px}
  .table-days{font-size:13px;color:var(--muted)}
  .action-cell{text-align:right;width:52px}
  .round-btn{border:1px solid #969e95;width:33px;height:33px;display:inline-grid;place-items:center;border-radius:50%;background:transparent;transition:background .18s,color .18s}
  .round-btn:hover{background:var(--ink);color:var(--cream)}
  .table-foot{margin-top:14px;font:11px/1.6 var(--mono);color:var(--muted)}
  .fare-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
  .fare-card{border:1px solid var(--line);border-top:3px solid #969c8f;background:#f9f6ed;display:flex;flex-direction:column;position:relative;overflow:hidden}
  .fare-card.featured{border-top-color:var(--orange);background:var(--night);color:var(--cream);border-inline-color:var(--night)}
  .fare-main{padding:24px 25px 19px;flex:1}
  .fare-over{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:23px;color:var(--muted)}
  .featured .fare-over,.featured p{color:#bdc8c6}
  .ticket-dashes{height:12px;width:35px;background:repeating-linear-gradient(90deg,currentColor 0 1px,transparent 1px 4px,currentColor 4px 6px,transparent 6px 8px);opacity:.6}
  .tag{color:var(--orange);font-size:9px;letter-spacing:.07em}
  .price{display:flex;align-items:baseline;gap:9px;margin-top:19px}
  .price strong{font:normal 42px/1.1 var(--serif);letter-spacing:-.06em}
  .price span{font-size:12px;color:var(--muted)}
  .featured .price span{color:#bdc8c6}
  .ticket-foot{border-top:1px dashed #a4a89e;position:relative;padding:16px 25px}
  .ticket-foot::before,.ticket-foot::after{content:"";position:absolute;top:-6px;width:11px;height:11px;background:var(--cream);border:1px solid var(--line);border-radius:50%;left:-7px}
  .ticket-foot::after{left:auto;right:-7px}
  .ticket-foot button{padding:0;display:flex;align-items:center;justify-content:space-between;width:100%;background:transparent;border:0;font-weight:700;font-size:13px}
  .ticket-foot button:hover{color:var(--rust)}
  .featured .ticket-foot button{color:var(--orange)}
  .quote-section{background:#e4e1d4;border-block:1px solid var(--line);overflow:hidden}
  .quote-layout{position:relative;display:grid;grid-template-columns:.65fr 2fr;gap:35px;padding-block:48px;align-items:start}
  .quote-mark{font:italic 90px/.9 var(--serif);color:var(--rust);margin-top:13px;height:48px}
  blockquote{font-size:clamp(24px,2.65vw,39px);letter-spacing:-.04em;line-height:1.24;max-width:850px}
  .quote-by{margin-top:18px;color:var(--muted);font:11px/1.5 var(--mono);letter-spacing:.04em}
  footer .wrap{padding-top:34px;padding-bottom:23px}
  .foot-top,.foot-bottom,.footer-links{display:flex;align-items:center;justify-content:space-between;gap:20px}
  .footer-links{gap:24px}
  .foot-bottom{margin-top:29px;padding-top:17px;border-top:1px solid #ffffff24;color:#b9c2c0;font:10px/1.5 var(--mono);letter-spacing:.05em}
  dialog{width:min(444px,calc(100% - 32px));max-height:90dvh;padding:0;border:1px solid var(--ink);border-radius:4px;background:var(--cream);color:var(--ink);box-shadow:0 22px 120px #0005}
  dialog::backdrop{background:#0e1920bc}
  .dialog-head{background:var(--night);color:var(--cream);padding:16px 23px;display:flex;align-items:center;justify-content:space-between}
  .dialog-head .brand{font-size:21px}
  .dialog-head .brand-mark{width:33px}
  .close{background:none;border:0;color:var(--cream);line-height:1;font-size:27px;padding:4px 7px}
  .dialog-body{padding:25px}
  .dialog-body h2{font-size:38px;margin:9px 0 15px}
  .dialog-body label{display:block;margin:17px 0 6px;font:700 11px var(--mono);text-transform:uppercase;letter-spacing:.08em}
  select{width:100%;border:1px solid #a8aea3;border-radius:3px;background:#fffcf4;color:var(--ink);padding:10px}
  .itinerary{margin:21px 0 0;border-block:1px dashed #aaafa5;padding:14px 0}
  .itinerary div{display:flex;justify-content:space-between;gap:10px;font-size:13px;padding:3px 0}
  .itinerary dt{color:var(--muted)}
  .itinerary dd{margin:0;font-weight:700}
  .dialog-note{font-size:12px;color:var(--muted);margin:14px 0}
  .dialog-body .btn{width:100%;background:var(--ink);color:var(--cream)}
  .sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
  @media(min-width:1500px){.hero{padding-block:65px}}
  @media(max-width:980px){
    .wrap{padding-inline:4.5vw}.hero{gap:26px;grid-template-columns:.91fr 1.09fr}
    h1{font-size:clamp(58px,7.2vw,73px)}.hero .kicker{font-size:9px}
    .plate figcaption{font-size:8px}.route-strip{gap:23px}.route-stats{gap:12px}.route-stats span+span{padding-left:12px}
    .feature{padding-inline:22px}.service{gap:10px}.fare-grid{gap:12px}.fare-main{padding:19px}.ticket-foot{padding-inline:19px}
  }
  @media(max-width:740px){
    .wrap{padding-inline:22px}.nav{height:67px;gap:14px}.brand{font-size:22px}.brand-mark{width:35px}
    .nav-links{gap:16px;margin-right:0}.nav-links a{font-size:12px}.nav .btn{padding:7px 10px;font-size:12px;gap:8px}
    .hero{grid-template-columns:1fr;gap:31px;padding-block:37px 27px}
    h1{font-size:clamp(68px,11.5vw,85px);margin:17px 0}.intro{max-width:450px}.hero-cta{margin-top:20px}
    .plate{max-width:580px;width:100%;justify-self:center}.plate figcaption{font-size:9px}
    .route-strip{flex-wrap:wrap;gap:12px 22px;padding:18px 0}.route-stats{font-size:10px}
    .section{padding-block:52px}.section-head{gap:15px;margin-bottom:27px;flex-wrap:wrap}.section-note{max-width:360px}
    .feature{padding-inline:15px}.feature h3{font-size:23px}.feature p{font-size:13px}.feature-art{width:42px}
    .service{flex-direction:column;align-items:flex-start;gap:2px}.service-name{font-size:18px}
    .fare-grid{grid-template-columns:1fr}.fare-main{display:grid;grid-template-columns:1fr auto;column-gap:16px;padding:18px 22px}
    .fare-over{grid-column:1/-1;margin-bottom:13px}.fare-card h3,.fare-card p{grid-column:1}.price{grid-column:2;grid-row:2/4;flex-direction:column;gap:2px;align-items:flex-end;justify-content:center;margin:0}
    .ticket-foot{padding:12px 22px}.quote-layout{grid-template-columns:1fr;gap:16px;padding-block:36px}.quote-mark{display:none}
  }
  @media(max-width:520px){
    .nav{flex-wrap:wrap;height:auto;min-height:76px;padding:13px 0 10px;gap:9px}.nav-links{width:100%;order:3;gap:23px}.nav .btn{margin-left:auto}
    h1{font-size:clamp(61px,15.6vw,78px)}.hero{padding-top:31px}.hero .kicker{letter-spacing:.12em}
    .route-strip{gap:12px 16px}.route-stats{width:100%;margin:0}.route-stats span+span{padding-left:16px}.stops{font-size:12px}.stop-line{width:36px}
    .route-label{font-size:9px}.section-head h2{margin-top:11px}h2{font-size:39px}
    .features{grid-template-columns:1fr;padding:0}.feature,.feature:first-child,.feature:last-child{position:relative;padding:21px 0 20px 64px;border:0;border-bottom:1px solid var(--line)}
    .feature-art{position:absolute;left:0;top:23px}.feature-top{margin:0}.feature-top .mono{display:none}.feature h3{font-size:26px}.feature p{margin-top:6px;font-size:14px}
    .schedule-head-note{font-size:10px}th{font-size:9px;letter-spacing:.055em}th,td{padding-inline:4px}th:first-child,td:first-child{padding-left:0}
    .service-name{font-size:16px}.service b{font-size:10px}.time{font-size:16px}.days-col{display:none}.action-cell{width:30px}.round-btn{width:28px;height:28px}
    .foot-top,.foot-bottom{align-items:flex-start;flex-direction:column}.foot-bottom{gap:5px}.footer-links a{font-size:12px}
  }
  @media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*::before,*::after{transition:none!important}}
</style>
</head>
