<script>
(() => {
  const dialog = document.getElementById('planner');
  const train = document.getElementById('train');
  const fare = document.getElementById('fare');
  const starts = ['19:40','20:30','21:45','23:10'];
  const ends = ['05:00','05:50','07:05','08:30'];
  const prices = ['$68','$124','$216'];
  function update() {
    document.getElementById('leave').textContent = starts[train.selectedIndex];
    document.getElementById('reach').textContent = ends[train.selectedIndex] + ' (+1 day)';
    document.getElementById('total').textContent = prices[fare.selectedIndex];
  }
  document.querySelectorAll('[data-plan]').forEach(button => {
    button.addEventListener('click', () => {
      if (button.dataset.train !== undefined) train.selectedIndex = Number(button.dataset.train);
      if (button.dataset.fare !== undefined) fare.selectedIndex = Number(button.dataset.fare);
      update();
      dialog.showModal();
      document.body.style.overflow = 'hidden';
    });
  });
  [train, fare].forEach(el => el.addEventListener('change', update));
  dialog.querySelector('.close').addEventListener('click', () => dialog.close());
  dialog.addEventListener('close', () => { document.body.style.overflow = ''; });
  dialog.addEventListener('click', event => {
    const box = dialog.getBoundingClientRect();
    if (event.target === dialog && (event.clientX < box.left || event.clientX > box.right || event.clientY < box.top || event.clientY > box.bottom)) dialog.close();
  });
  document.getElementById('download').addEventListener('click', () => {
    const text = [
      'DUNE LINE / EASTBOUND ITINERARY', 'Sola Dunes → Luma City', '',
      train.options[train.selectedIndex].text, 'Runs nightly · 684 km · 9 h 20 min',
      'Departs Sola Dunes: ' + starts[train.selectedIndex],
      'Arrives Luma City: ' + ends[train.selectedIndex] + ' the following morning',
      'Passage: ' + fare.options[fare.selectedIndex].text + ' per traveller, one way',
      '', 'Travel plan only — Dune Line is a fictional railway.'
    ].join('\n');
    const url = URL.createObjectURL(new Blob([text], {type:'text/plain;charset=utf-8'}));
    const link = document.createElement('a');
    link.href = url;
    link.download = 'Dune-Line-itinerary.txt';
    document.body.appendChild(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1500);
  });
})();
</script>
